def keyPattern = /^\s{8,}([A-Za-z][A-Za-z0-9 _.\-]*?)\s*[:=](.*)$/;
def key = null;
def value = new StringBuilder();
for (def line : /\r?\n/.split(ctx.winlog.event_data.ContextInfo)) {
  def matcher = keyPattern.matcher(line);
  if (matcher.matches()) {
    if (key != null) {
      ctx.winlog.event_data[key] = value.toString().trim();
    }
    key = matcher.group(1);
    value = new StringBuilder(matcher.group(2));
  } else if (key != null) {
    value.append((char)10).append(line);
  }
}
if (key != null) {
  ctx.winlog.event_data[key] = value.toString().trim();
}

def newEventData = new HashMap();
for (entry in ctx.winlog.event_data.entrySet()) {
  def newKey = /\s/.matcher(entry.getKey().toString()).replaceAll("");
  newEventData.put(newKey, entry.getValue());
}
ctx.winlog.event_data = newEventData;

// Entropy Variance from: https://github.com/elastic/toutoumomoma/blob/be287c9c0d0e435572e3889a6584199983c688f0/toutoumomoma.go#L326-L363.
String script = ctx._temp.script_block_no_signature;

int length = script.length();
if (length == 0) {
  return;
}

// Skip signature only scripts:
// - Inspect only line 2 (line 1 can be truncated mid-signature).
// - Match "# " + base64-ish content at the fixed signature line length (64 chars).
int lf = 10;    // '\n'
int cr = 13;    // '\r'
int hash = 35;  // '#'
int space = 32; // ' '
int sigLineLen = 64; // Content length, excluding "# " prefix.

int firstLineEnd = -1;
for (int idx = 0; idx < length; idx++) {
  if (script.charAt(idx) == lf) {
    firstLineEnd = idx;
    break;
  }
}

if (firstLineEnd > 0) {
  int secondLineStart = firstLineEnd + 1;
  if (secondLineStart < length) {
    int secondLineEnd = length;
    for (int idx = secondLineStart; idx < length; idx++) {
      if (script.charAt(idx) == lf) {
        secondLineEnd = idx;
        break;
      }
    }

    if (secondLineEnd > secondLineStart && script.charAt(secondLineEnd - 1) == cr) {
      secondLineEnd--;
    }

    if (secondLineStart < secondLineEnd && script.charAt(secondLineStart) == hash) {
      int contentStart = secondLineStart + 1;
      if (contentStart < secondLineEnd && script.charAt(contentStart) == space) {
        contentStart++;
      }
      int lineLen = secondLineEnd - contentStart;
      if (lineLen == sigLineLen) {
        boolean base64Line = true;
        for (int i = contentStart; i < secondLineEnd; i++) {
          int c = (int) script.charAt(i);
          if (!((c >= 65 && c <= 90) || (c >= 97 && c <= 122) ||
                (c >= 48 && c <= 57) || c == 43 || c == 47 || c == 61)) {
            base64Line = false;
            break;
          }
        }
        if (base64Line) {
          return;
        }
      }
    }
  }
}

script = java.text.Normalizer.normalize(script, java.text.Normalizer.Form.NFC);

length = script.length();
if (length == 0) {
  return;
}

int[] counts = new int[65536];
int[] seen = new int[length];
int seenCount = 0;
int uniqueSymbols = 0;
for (int i = 0; i < length; i++) {
    int ch = script.charAt(i);
    if (counts[ch] == 0) {
        counts[ch] = 1;
        seen[seenCount++] = ch;
        uniqueSymbols++;
    } else {
        counts[ch]++;
    }
}

double invLog2 = 1.0 / Math.log(2.0);
double entropy = 0.0;
double surprisalVar = 0.0;
double pSum = 0.0;

for (int i = 0; i < seenCount; i++) {
    int code = seen[i];
    double cnt = (double) counts[code];
    double p = cnt / (double) length;
    double l2p = Math.log(p) * invLog2;

    pSum += p;
    double tmp = entropy;
    entropy = tmp + (p / pSum) * (l2p - tmp);
    surprisalVar += p * (l2p - tmp) * (l2p - entropy);
}

surprisalVar = Math.max(0.0, surprisalVar);
double surprisalSd = Math.sqrt(surprisalVar);
double entropyBits = -entropy;
if (entropyBits == -0.0) {
    entropyBits = 0.0;
}

double normalizedEntropy = 0.0;
if (length > 1) {
    double maxEntropy = Math.log((double) length) * invLog2; // max bits if every character is unique
    normalizedEntropy = entropyBits / maxEntropy;           // scale 0..1 against script length
    if (normalizedEntropy < 0.0) normalizedEntropy = 0.0;
    else if (normalizedEntropy > 1.0) normalizedEntropy = 1.0;
}

ctx.powershell.file.script_block_entropy_bits = entropyBits;
ctx.powershell.file.script_block_entropy_normalized = normalizedEntropy;
ctx.powershell.file.script_block_surprisal_stdev = surprisalSd;
ctx.powershell.file.script_block_length = length;
ctx.powershell.file.script_block_unique_symbols = uniqueSymbols;

def parseRawDetail(String raw) {
    Pattern detailRegex = /^([^(]+)\(([^)]+)\)\:\s*(.+)?$/;
    Pattern parameterBindingRegex = /name\=(.+);\s*value\=(.+)$/;

    def matcher = detailRegex.matcher(raw);
    if (!matcher.matches()) {
        return ["value": raw];
    }
    def matches = new ArrayList();
    for (def i = 0; i <= matcher.groupCount(); i++) {
        matches.add(matcher.group(i));
    }

    if (matches.length != 4) {
        return ["value": raw];
    }                

    if (matches[1] != "ParameterBinding") {
        return [
            "type": matches[1], 
            "related_command": matches[2], 
            "value": matches[3]
        ];
    }

    matcher = parameterBindingRegex.matcher(matches[3]);
    if (!matcher.matches()) {
        return ["value": matches[4]];
    }
    def nameValMatches = new ArrayList();
    for (def i = 0; i <= matcher.groupCount(); i++) {
        nameValMatches.add(matcher.group(i));
    }
    if (nameValMatches.length !== 3) {
        return ["value": matches[3]];
    }

    return [
        "type": matches[1],
        "related_command": matches[2],
        "name": nameValMatches[1],
        "value": nameValMatches[2]
    ];
}

if (ctx._temp == null) {
    ctx._temp = new HashMap();
}

if (ctx._temp.details == null) {
    ctx._temp.details = new ArrayList();
}

def values = ctx.winlog?.event_data[params["field"]];
if (values != null && values.length > 0) {
    for (v in values) {
        ctx._temp.details.add(parseRawDetail(v));
    }
}

// appendBSBytes appends n '\\' bytes to b and returns the resulting slice.
def appendBSBytes(StringBuilder b, int n) {
    for (; n > 0; n--) {
        b.append('\\');
    }
    return b;
}

// readNextArg splits command line string cmd into next
// argument and command line remainder.
def readNextArg(String cmd) {
    def b = new StringBuilder();
    boolean inquote;
    int nslash;
    for (; cmd.length() > 0; cmd = cmd.substring(1)) {
        def c = cmd.charAt(0);
        if (c == (char)' ' || c == (char)0x09) {
            if (!inquote) {
                return [
                    "arg":  appendBSBytes(b, nslash).toString(),
                    "rest": cmd.substring(1)
                ];
            }
        } else if (c == (char)'"') {
            b = appendBSBytes(b, nslash/2);
            if (nslash%2 == 0) {
                // use "Prior to 2008" rule from
                // http://daviddeley.com/autohotkey/parameters/parameters.htm
                // section 5.2 to deal with double double quotes
                if (inquote && cmd.length() > 1 && cmd.charAt(1) == (char)'"') {
                    b.append(c);
                    cmd = cmd.substring(1);
                }
                inquote = !inquote;
            } else {
                b.append(c);
            }
            nslash = 0;
            continue;
        } else if (c == (char)'\\') {
            nslash++;
            continue;
        }
        b = appendBSBytes(b, nslash);
        nslash = 0;
        b.append(c);
    }
    return [
        "arg":  appendBSBytes(b, nslash).toString(), 
        "rest": ''
    ];
}

// commandLineToArgv splits a command line into individual argument
// strings, following the Windows conventions documented
// at http://daviddeley.com/autohotkey/parameters/parameters.htm#WINARGV
// Original implementation found at: https://github.com/golang/go/commit/39c8d2b7faed06b0e91a1ad7906231f53aab45d1
def commandLineToArgv(String cmd) {
    def args = new ArrayList();
    while (cmd.length() > 0) {
        if (cmd.charAt(0) == (char)' ' || cmd.charAt(0) == (char)0x09) {
            cmd = cmd.substring(1);
            continue;
        }
        def next = readNextArg(cmd);
        cmd = next.rest;
        args.add(next.arg);
    }
    return args;
}

ctx.process.args = commandLineToArgv(ctx.process.command_line);
ctx.process.args_count = ctx.process.args.length;

def path = ctx.winlog.event_data.ScriptName;
def idx = path.lastIndexOf("\\");
if (idx > -1) {
    if (ctx.file == null) {
        ctx.file = new HashMap();
    }
    ctx.file.name = path.substring(idx+1);
    ctx.file.directory = path.substring(0, idx);

    def extIdx = path.lastIndexOf(".");
    if (extIdx > -1) {
        ctx.file.extension = path.substring(extIdx+1);
    }
}
